ALTER TABLE public.affaire_documents ADD COLUMN source_email_id uuid REFERENCES public.emails_entrants(id) ON DELETE SET NULL, ADD COLUMN source_attachment_id text;
CREATE UNIQUE INDEX affaire_documents_source_attachment_unique ON public.affaire_documents(affaire_id, source_email_id, source_attachment_id) WHERE deleted_at IS NULL AND source_email_id IS NOT NULL;
CREATE POLICY affaire_documents_business_read ON public.affaire_documents FOR SELECT TO authenticated USING (deleted_at IS NULL AND public.current_user_has_capability('section.affaires') AND EXISTS (SELECT 1 FROM public.affaires a WHERE a.id = affaire_id));
CREATE POLICY affaire_documents_business_insert ON public.affaire_documents FOR INSERT TO authenticated WITH CHECK (uploaded_by = auth.uid() AND public.current_user_has_capability('section.affaires') AND EXISTS (SELECT 1 FROM public.affaires a WHERE a.id = affaire_id));
CREATE POLICY affaires_photos_business_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'affaires-photos' AND EXISTS (SELECT 1 FROM public.affaire_documents d WHERE d.storage_path = name AND d.deleted_at IS NULL));
CREATE POLICY affaires_photos_business_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'affaires-photos' AND public.current_user_has_capability('section.affaires') AND EXISTS (SELECT 1 FROM public.affaires a WHERE a.id::text = (storage.foldername(name))[1]));